// Lee la ficha con la respuesta de OpenAI y la compara contra la hoja "Referencia" (la fuente de verdad).
const r = $('OpenAI analizar ficha').first().json;
let t = '';
const msg = (r.output || []).find(o => o.type === 'message');
if (msg) { const p = (msg.content || []).find(c => c.type === 'output_text'); t = p ? p.text : ''; }
if (!t) t = r.text || r.output_text || (r.message && r.message.content) || '';
if (!t) throw new Error('OpenAI no devolvió datos');
const d = (typeof t === 'object') ? t : JSON.parse(String(t).replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim());

const txt = v => String(v === undefined || v === null ? '' : v).trim();
const pick = (o, ks) => { for (const k of Object.keys(o || {})) if (ks.includes(k.toLowerCase())) return o[k]; return undefined; };
const norm = v => txt(v).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const num = v => { const n = parseInt(txt(v).replace(/[^\d]/g, ''), 10); return isNaN(n) ? null : n; };

// Respaldo sin IA para proveedor y artículo (igual que en la carga).
let textoPdf = '';
try { textoPdf = String($('Extraer texto del PDF').first().json.text || ''); } catch (e) {}
const fProv = txt(d.proveedor) || (/PROVEEDOR\s*:\s*([^\n\r]+?)(?:\s{2,}|\s+(?:TALLES?|COLOR|ART[IÍ]CULO|NOMBRE|TEMPORADA)\b|[\n\r]|$)/i.exec(textoPdf) || [])[1] || '';
const fArt = txt(d.articulo) || (/ART[IÍ]CULO\s*:\s*(\d{3,})/i.exec(textoPdf) || [])[1] || '';

const lista = pick(d, ['colores', 'colors']);
const fColores = (Array.isArray(lista) ? lista : []).map(c => ({
  codigo: txt(pick(c, ['codigo', 'código', 'code'])), color: txt(pick(c, ['color', 'nombre', 'name'])), cantidad: num(pick(c, ['cantidad', 'qty', 'prendas']))
}));
const kTotal = Object.keys(d).find(k => /total/i.test(k));
const ficha = { articulo: fArt, modelo: txt(d.modelo), temporada: txt(d.temporada), linea: txt(d.linea), ordenCompra: txt(d.ordenCompra),
  proveedor: txt(fProv), tela: txt(d.tela), cantidadTotal: num(kTotal ? d[kTotal] : null), colores: fColores };

const w = $('Webhook verificar').first();
const archivo = ((w.binary || {}).file || {}).fileName || txt(((w.json || {}).body || {}).nombre) || '';

// ---- Buscar la fila de referencia: por artículo si la ficha lo trae; si no, por modelo ----
const ref = $input.all().map(i => i.json).filter(x => txt(x['Artículo']) || txt(x['Modelo']));
let filas = [], clave = '';
if (ficha.articulo) {
  clave = 'Artículo ' + ficha.articulo;
  filas = ref.filter(x => norm(x['Artículo']) === norm(ficha.articulo));
  if (filas.length && ficha.ordenCompra) {
    const conOc = filas.filter(x => !txt(x['Orden de compra']) || norm(x['Orden de compra']) === norm(ficha.ordenCompra));
    if (conOc.length) filas = conOc;
  }
}
if (!filas.length && ficha.modelo) {
  clave = (ficha.articulo ? clave + ' (no encontrado); ' : '') + 'Modelo ' + ficha.modelo;
  filas = ref.filter(x => norm(x['Modelo']) === norm(ficha.modelo));
}
if (!filas.length) {
  return [{ json: { archivo, estado: 'SIN_REFERENCIA', clave: clave || '(la ficha no trae artículo ni modelo)', ficha, campos: [], colores: [],
    resumen: 'No se encontró esta ficha en la hoja Referencia.' } }];
}
const base = filas[0];
const R = { articulo: txt(base['Artículo']), modelo: txt(base['Modelo']), temporada: txt(base['Temporada']), linea: txt(base['Línea']),
  ordenCompra: txt(base['Orden de compra']), proveedor: txt(base['Proveedor']), tela: txt(base['Tela']), cantidadTotal: num(base['Cantidad total de prendas']) };

// ---- Comparación de campos ----
const campos = [];
const comparar = (campo, etiqueta, f, rf, modo) => {
  if (!rf && rf !== 0) return;                       // la referencia no tiene el dato: no hay contra qué comparar
  let res;
  if (f === '' || f === null) res = 'falta_en_ficha';
  else if (modo === 'num') res = (f === rf) ? 'ok' : 'diferente';
  else if (modo === 'contiene') { const a = norm(f), b = norm(rf); res = (a === b || a.includes(b) || b.includes(a)) ? 'ok' : 'diferente'; }
  else res = (norm(f) === norm(rf)) ? 'ok' : 'diferente';
  campos.push({ campo: etiqueta, ficha: f === null ? '' : f, referencia: rf, resultado: res });
};
comparar('articulo', 'Artículo', ficha.articulo, R.articulo);
comparar('modelo', 'Modelo', ficha.modelo, R.modelo);
comparar('temporada', 'Temporada', ficha.temporada, R.temporada);
comparar('linea', 'Línea', ficha.linea, R.linea);
comparar('ordenCompra', 'Orden de compra', ficha.ordenCompra, R.ordenCompra);
comparar('proveedor', 'Proveedor', ficha.proveedor, R.proveedor, 'contiene');
comparar('tela', 'Tela', ficha.tela, R.tela, 'contiene');
comparar('cantidadTotal', 'Cantidad total', ficha.cantidadTotal, R.cantidadTotal, 'num');

// ---- Comparación de colores (por código; si no hay código, por nombre) ----
const colores = [];
const usados = new Set();
for (const x of filas) {
  const rc = { codigo: txt(x['Código de color']), color: txt(x['Color']), cantidad: num(x['Cantidad del color']) };
  if (!rc.codigo && !rc.color) continue;
  const idx = fColores.findIndex((c, i) => !usados.has(i) && ((rc.codigo && c.codigo && norm(c.codigo) === norm(rc.codigo)) || (norm(c.color) && norm(c.color) === norm(rc.color))));
  if (idx === -1) { colores.push({ codigo: rc.codigo, color: rc.color, ficha: null, referencia: rc.cantidad, resultado: 'falta_en_ficha' }); continue; }
  usados.add(idx);
  const fc = fColores[idx];
  let res = 'ok';
  if (rc.cantidad !== null && fc.cantidad === null) res = 'falta_en_ficha';
  else if (rc.cantidad !== null && fc.cantidad !== rc.cantidad) res = 'diferente';
  colores.push({ codigo: rc.codigo || fc.codigo, color: rc.color || fc.color, ficha: fc.cantidad, referencia: rc.cantidad, resultado: res });
}
fColores.forEach((c, i) => { if (!usados.has(i)) colores.push({ codigo: c.codigo, color: c.color, ficha: c.cantidad, referencia: null, resultado: 'falta_en_referencia' }); });

const malos = campos.filter(c => c.resultado !== 'ok').length + colores.filter(c => c.resultado !== 'ok').length;
return [{ json: { archivo, estado: malos ? 'CON_DIFERENCIAS' : 'OK', clave, ficha, campos, colores, diferencias: malos,
  resumen: malos ? malos + ' diferencia(s) encontradas.' : 'Todo coincide con la referencia.' } }];
